[TFMPageType('OrderLines', "Order Lines")]
class TFMPageOrderLinesConfiguration extends TFMListPageConfiguration
{

    boolean			suggestQuantity;
    TFMListId		listId;
    TFMServiceID	serviceId;
    boolean			clearOrderLevelRegistrations;
    boolean			viewRegistrationsEnabled;
    TFMPageID			viewRegistrationsNavigateTo;
    TFMPageTitleString				viewRegistrationsTitle;
    TFMActionOnEmptyList    actionOnEmptyList;
	boolean			deleteOrderRegistrationsEnabled;

    TFMPageTitleString				deleteOrderRegistrationsTitle;

    boolean			postOrderEnabled;
    TFMPageID       postOrderNavigateTo;

    boolean			finishOrderEnabled;
    boolean			finishOrderAlwaysEnabled;

    boolean			searchEnabled;
    TFMPageID       searchNavigateTo;

    boolean			cancelRemainingLineQuantityEnabled;
    boolean			orderLevelRegistrationsEnabled;
    boolean			toggleOrderLineGroupingEnabled;

    str				gs1SearchTerm;
    TFMScanToSelectBehaviour behaviour;
    str             converterExpression;
    str             converterExpressionAis;
    boolean         converterConvertGS1Input;
    TFMLineSelection lineSelection;

}

