protected void populateXmlWithAdditionalProperties(XmlElement _configNode, TFMPage _page)
{
    super(_configNode, _page);
    TFMPinnableValues::populateConfigurationXMLWithPinnableValues(_configNode,_page);
}

protected Map populateXML(XmlElement _configNode, XmlElement _pageNode)
{
    XmlElement  scanToSelectBehaviourElement;
    XmlElement  converter;
    Map returnMap = super(_configNode, _pageNode);

    // this has been added because the Mobile WMS Device app will convert all barcodes to a GS1 if the converter exists in the XML output. In time this can be deleted because the App will handle it.
    if(!this.parmScanToSelectBehaviourExpression() || !this.parmScanToSelectBehaviourExpressionAis())
    {
        if(returnMap.exists('converter'))
        {
            returnMap.remove('converter');

            scanToSelectBehaviourElement = _configNode.getNamedElement('scanToSelectBehaviour');
            if(scanToSelectBehaviourElement)
            {
                converter = scanToSelectBehaviourElement.getNamedElement('converter');
                if(converter)
                {
                    scanToSelectBehaviourElement.removeChild(converter);
                }
            }
        }
    }
    return returnMap;
}
